import React, { useState } from "react";
import { Box, AppBar, Toolbar, Typography, Drawer, List, ListItem, ListItemIcon, ListItemText, IconButton } from "@mui/material";
import { Dashboard as DashboardIcon, HowToVote, BarChart, ExitToApp } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

const drawerWidth = 240;

const Dashboard = () => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("Dashboard");

  return (
    <Box sx={{ display: "flex", minHeight: "100vh" }}>
      {/* Sidebar Navigation */}
      <Drawer
        variant="permanent"
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          [`& .MuiDrawer-paper`]: { width: drawerWidth, boxSizing: "border-box", backgroundColor: "white" },
        }}
      >
        <Toolbar />
        <List>
          <ListItem button onClick={() => setActiveTab("Dashboard")}> 
            <ListItemIcon><DashboardIcon /></ListItemIcon>
            <ListItemText primary="Dashboard" />
          </ListItem>
          <ListItem button onClick={() => navigate("/vote")}>
            <ListItemIcon><HowToVote /></ListItemIcon>
            <ListItemText primary="Vote" />
          </ListItem>
          <ListItem button onClick={() => setActiveTab("Results")}>
            <ListItemIcon><BarChart /></ListItemIcon>
            <ListItemText primary="Results" />
          </ListItem>
        </List>
        <Box sx={{ flexGrow: 1 }}></Box>
        <List>
          <ListItem button onClick={() => navigate("/logout")} sx={{ color: "#d32f2f" }}>
            <ListItemIcon sx={{ color: "#d32f2f" }}><ExitToApp /></ListItemIcon>
            <ListItemText primary="Logout" />
          </ListItem>
        </List>
      </Drawer>
      
      {/* Main Content */}
      <Box sx={{ flexGrow: 1, display: "flex", flexDirection: "column" }}>
        <AppBar position="fixed" sx={{ width: `calc(100% - ${drawerWidth}px)`, ml: `${drawerWidth}px`, backgroundColor: "#007bff" }}>
          <Toolbar>
            <Typography variant="h6" noWrap component="div">
              Voter's Dashboard
            </Typography>
          </Toolbar>
        </AppBar>
        
        <Box sx={{ flexGrow: 1, p: 3, mt: 8, display: "flex", justifyContent: "center", alignItems: "center", backgroundColor: "rgba(100, 200, 225, 0.3)", minHeight: "100vh" }}>
          <Typography variant="h4" fontWeight="bold">
            {activeTab === "Dashboard" ? "Welcome to the Dashboard" : "Election Results"}
          </Typography>
        </Box>
      </Box>
    </Box>
  );
};

export default Dashboard;
